@Composable
fun BloodPressureReadingCard(connected: Boolean = true) {
    Column(modifier = Modifier.padding(horizontal = 16.dp)) {
        Text(
            text = "Blood Pressure Reading",
            fontSize = 18.sp,
            fontWeight = FontWeight.SemiBold,
            color = Color.Black,
            modifier = Modifier.padding(bottom = 12.dp)
        )

        Card(
            modifier = Modifier.fillMaxWidth(),
            colors = CardDefaults.cardColors(containerColor = Color(0xFFD85C5C)),
            shape = RoundedCornerShape(16.dp)
        ) {
            Column {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(16.dp),
                    horizontalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    BPReadingItem("135", "SYS", "mmHg", Modifier.weight(1f))
                    BPReadingItem("90", "DIA", "mmHg", Modifier.weight(1f))
                    BPReadingItem("98", "Pulse", "BPM", Modifier.weight(1f))
                }

                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(Color(0xFF2C2C2C))
                        .padding(12.dp)
                ) {
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.spacedBy(8.dp)
                    ) {
                        Box(
                            modifier = Modifier
                                .size(10.dp)
                                .clip(CircleShape)
                                .background(if (connected) Color(0xFF4CAF50) else Color(0xFFF44336))
                        )
                        Text(
                            text = if (connected) "Connected to Sfigmomanometer" else "Not connected to Sfigmomanometer",
                            fontSize = 14.sp,
                            color = Color.White
                        )
                    }
                }
            }
        }
    }
}

